with with_gaps as (select *, case when event_time - lag(event_time) over (partition by event_type order by event_time, id) > interval 7 days then 1 else 0 end as session_start_flag from web_events), sessions_web_events as (select id, event_type, event_time, duration_sec, sum(session_start_flag) over (partition by event_type order by event_time, id rows between unbounded preceding and current row) as session_id_2 from with_gaps) select id, event_type, event_time, case when event_type rlike '^(purchase|add_to_cart)$' then 'PRIORITY' else 'CORE' end as event_type_zone from sessions_web_events order by event_type_zone desc
